// HARDENED: Non-blocking reactive token bucket rate limiter
Mono filter(ServerWebExchange exchange, GatewayFilterChain chain) {
    return tokenBucketLimiter.tryConsume(clientIp)
        .flatMap(allowed -> allowed ? 
            chain.filter(exchange).timeout(Duration.ofMillis(300)) : 
            exchange.getResponse().setStatusCode(HttpStatus.TOO_MANY_REQUESTS).setComplete()
        );
}
